/* A replayable, non-interactive robot greeting on every XR entry. */
(()=>{const T=AFRAME.THREE;
const sealDefinition={
 init(){this.seen=false;try{this.seen=sessionStorage.getItem('globiquest.xr-welcome.v1')==='seen'}catch{}this.reduced=!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;this.listeners=[];window.globiquest.replayXRWelcome=()=>{this.clear();this.closeReplay=true;this.waiting=3;if(!this.el.is('vr-mode')){this.seen=false;if(typeof notify==='function')notify('Enter XR for a seal-bot hello.')}};this.replayButton=document.createElement('button');this.replayButton.type='button';this.replayButton.id='cuteHelloReplay';this.replayButton.textContent='♡ Cute hello';this.replayButton.onclick=()=>window.globiquest.replayXRWelcome();document.getElementById('spatialDock')?.append(this.replayButton);const on=(el,name,fn)=>{el?.addEventListener(name,fn);this.listeners.push(()=>el?.removeEventListener(name,fn))};on(this.el,'enter-vr',()=>{this.clear();this.closeReplay=true;this.waiting=3;this.started=null});on(this.el,'exit-vr',()=>this.clear());if(this.el.is('vr-mode')){this.closeReplay=true;this.waiting=3;this.started=null}},
 create(){const root=this.root=new T.Group();root.name='welcome-chubby-robot';root.userData.design='seal-robot';this.robotMatcap=null;const mats=new Map(),mat=(color,glow=false)=>{const key=color+glow;if(!mats.has(key))mats.set(key,new T.MeshPhysicalMaterial({color,roughness:glow?.48:.78,metalness:0,clearcoat:glow?.18:.04,clearcoatRoughness:.32,emissive:color,emissiveIntensity:glow?.025:.01,transparent:false,opacity:1}));return mats.get(key)},ball=(x,y,z,r,color,parent=root,glow=false)=>{const m=new T.Mesh(new T.SphereGeometry(r,28,18),mat(color,glow));m.position.set(x,y,z);parent.add(m);return m};ball(0,-.055,0,.165,'#fff6e9').scale.set(1,.86,1);ball(0,.065,.026,.145,'#fff6e9');ball(0,-.055,.145,.082,'#fffdf8').scale.set(1,.8,.22);for(const side of [-1,1]){ball(side*.054,.069,.156,.036,'#e8efff').scale.set(1,1.12,.4);ball(side*.054,.07,.171,.025,'#699fbe',root,true).scale.set(.85,1.08,.32);ball(side*.054,.071,.18,.014,'#477b9c',root,true).scale.set(.85,1,.3);ball(side*.054-.008,.08,.178,.009,'#ffffff');ball(side*.086,.018,.135,.022,'#f8cfd1').scale.set(1,.55,.27);const joint=new T.Mesh(new T.TorusGeometry(.032,.005,8,32),mat('#b9ddd9'));joint.position.set(side*.151,-.057,.05);joint.rotation.y=side*.4;root.add(joint)}ball(0,.011,.176,.016,'#b6dbe9').scale.set(1.1,.65,.5);const headphoneBand=new T.Mesh(new T.TorusGeometry(.171,.012,10,56,Math.PI),mat('#ded7f3'));headphoneBand.position.set(0,.065,-.01);root.add(headphoneBand);for(const side of [-1,1]){ball(side*.166,.062,.008,.048,'#e4f3ee').scale.set(.42,1.07,.95);ball(side*.183,.062,.008,.039,'#ded7f3').scale.set(.3,1,.92);ball(side*.191,.062,.009,.017,'#f9fbf3').scale.set(.2,1,1)}root.userData.headphones=true;const smile=new T.Mesh(new T.TorusGeometry(.029,.0045,8,28,Math.PI),mat('#527e98'));smile.rotation.z=Math.PI;smile.position.set(0,-.009,.18);root.add(smile);const antenna=new T.Mesh(new T.CylinderGeometry(.006,.006,.045,10),mat('#c5e4de'));antenna.position.set(0,.218,-.015);root.add(antenna);this.star=ball(0,.248,-.015,.017,'#ffdae2',root,true);ball(0,-.067,.166,.017,'#bcebdd',root,true).scale.set(1,1,.2);this.paws=[];this.contactRings=[];for(const side of [-1,1]){const arm=new T.Group();arm.position.set(side*.125,-.065,.125);ball(0,0,0,.047,'#fff6e9',arm).scale.set(1.3,.7,.45);ball(0,0,.02,.023,'#c7ece3',arm).scale.set(1,.7,.17);const contact=new T.Mesh(new T.TorusGeometry(.041,.003,6,40),new T.MeshBasicMaterial({color:'#d0fff4',transparent:true,opacity:0,depthWrite:false}));contact.position.z=.027;contact.visible=false;arm.add(contact);this.contactRings.push(contact);root.add(arm);this.paws.push(arm)}this.tail=new T.Group();this.tail.position.set(0,-.08,-.15);for(const side of [-1,1])ball(side*.038,0,-.035,.045,'#eceaf8',this.tail).scale.set(1,.4,1.25);root.add(this.tail);const sparkVertices=[];for(let i=0;i<12;i++){const a=i*Math.PI/6;for(const r of [.035,.065])sparkVertices.push(Math.cos(a)*r,Math.sin(a)*r,0)}this.contactSpark=new T.LineSegments(new T.BufferGeometry().setAttribute('position',new T.Float32BufferAttribute(sparkVertices,3)),new T.LineBasicMaterial({color:'#f6df9b',transparent:true,opacity:0,depthWrite:false}));this.contactSpark.position.set(0,.015,.24);this.contactSpark.visible=false;root.add(this.contactSpark);const fill=new T.PointLight('#ffffff',.18,1.2,2);fill.position.set(0,.18,.48);root.add(fill);this.el.object3D.add(root);this.seen=true;try{sessionStorage.setItem('globiquest.xr-welcome.v1','seen')}catch{}},
 tick(time){if(!this.el.is('vr-mode'))return;if(this.waiting){if(--this.waiting)return;const pose=window.globiquest.xrHeadPose?.();if(!pose){this.waiting=1;return}this.anchor=pose.position.clone();this.forward=pose.forward.clone().normalize();this.right=this.forward.clone().cross(new T.Vector3(0,1,0)).normalize();this.create();this.started=time}if(!this.root||this.started===null)return;const t=(time-this.started)/1000;if(t>5.8){this.clear();return}let distance,side,height;if(t<1.3){const u=t/1.3,ease=1-Math.pow(1-u,3);distance=this.reduced?1.5:this.closeReplay?1.8-1.38*ease:1.8-.2*ease;side=-.12*(1-ease);height=-.03+Math.sin(u*Math.PI)*.16}else if(t<2.5){const u=(t-1.3)/1.2;distance=this.reduced?1.5:this.closeReplay?.42+1.28*(1-Math.cos(u*Math.PI))/2:1.6+.1*(1-Math.cos(u*Math.PI))/2;side=0;height=-.03+Math.sin(u*Math.PI*2)*.055*(1-u)}else{const u=Math.min(1,(t-2.5)/2.5);distance=1.7+u*.6;side=-u*.45;height=-.03+u*.4}this.root.position.copy(this.anchor).addScaledVector(this.forward,distance).addScaledVector(this.right,side);this.root.position.y+=height;this.root.lookAt(this.anchor);this.root.rotateZ(Math.sin(t*3)*.07);this.root.scale.setScalar(1);this.animateGlassSpark(t);this.animateGoodbye(t);const sparkle=Math.max(0,1-Math.abs(t-1.45)/.3);if(this.contactSpark){this.contactSpark.visible=!this.reduced&&sparkle>0;this.contactSpark.material.opacity=sparkle*.85;this.contactSpark.scale.setScalar(1+(1-sparkle)*1.5);this.contactSpark.rotation.z=t*.5}this.star.rotation.y=t*1.5;this.wings?.forEach((wing,i)=>wing.rotation.z=(i?1:-1)*(.25+Math.sin(t*11)*.45));if(this.tail)this.tail.rotation.y=Math.sin(t*6)*.45;this.paws?.forEach((paw,i)=>{const boop=Math.exp(-Math.pow((t-1.45)/.38,2));paw.position.y=-.065+Math.sin(t*5+i*Math.PI)*.018+boop*.09;paw.position.z=.125+boop*.075;paw.position.x=(i?1:-1)*(.125-boop*.025);paw.scale.z=1-boop*.45;const contact=this.contactRings?.[i];if(contact){contact.visible=boop>.3;contact.material.opacity=boop*.55;contact.scale.setScalar(1+(1-boop)*.5)}})},
 animateGlassSpark(t){if(t<1.18||t>2.65){if(this.glassSpark)this.glassSpark.visible=false;return}if(!this.glassSpark){this.glassSpark=new T.Group();this.glassSpark.name='glasses-tap-starbursts';this.el.object3D.add(this.glassSpark);const pose=window.globiquest.xrHeadPose?.()||{position:this.anchor,forward:this.forward},point=pose.position.clone().addScaledVector(pose.forward,.48);this.glassSpark.position.copy(this.glassSpark.parent.worldToLocal(point));this.glassSpark.lookAt(pose.position);for(const side of [-1,1])for(let i=0;i<5;i++){const shape=new T.Shape();for(let j=0;j<10;j++){const a=j*Math.PI/5,r=j%2?.007:.017,x=Math.cos(a)*r,y=Math.sin(a)*r;if(j)shape.lineTo(x,y);else shape.moveTo(x,y)}shape.closePath();const star=new T.Mesh(new T.ShapeGeometry(shape),new T.MeshBasicMaterial({color:['#f6dfa0','#c6e8e5','#f2cddd','#ded4f4','#fff2c7'][i],transparent:true,opacity:0,side:T.DoubleSide,depthTest:false,depthWrite:false,toneMapped:false}));star.renderOrder=29000;star.userData.spark={side,i};this.glassSpark.add(star)}}const u=T.MathUtils.clamp((t-1.18)/1.47,0,1),alpha=Math.min(1,u*8)*(1-Math.pow(u,2));this.glassSpark.visible=true;this.glassSpark.children.forEach(star=>{const {side,i}=star.userData.spark,a=i*Math.PI*2/5,r=.016+u*.065;star.position.set(side*.085+Math.cos(a)*r,.01+Math.sin(a)*r,0);star.scale.setScalar(this.reduced?.8:1+Math.sin(u*Math.PI)*.35);star.rotation.z=this.reduced?0:u*side*.8;star.material.opacity=alpha})},
 animateGoodbye(t){if(t<2.5)return;if(!this.exitBody){this.exitBody=new T.Group();for(const child of [...this.root.children])this.exitBody.add(child);this.root.add(this.exitBody);this.bubble=new T.Mesh(new T.SphereGeometry(.26,24,16),new T.MeshBasicMaterial({color:'#cce9f1',transparent:true,opacity:.12,depthWrite:false}));this.root.add(this.bubble);this.popRing=new T.Mesh(new T.TorusGeometry(.25,.006,6,48),new T.MeshBasicMaterial({color:'#edcce4',transparent:true,opacity:0,depthWrite:false}));this.root.add(this.popRing)}const shrink=T.MathUtils.clamp((t-4)/1,0,1),pop=T.MathUtils.clamp((t-5)/.8,0,1);this.exitBody.scale.set(this.reduced?1-shrink:1-shrink+Math.sin(t*15)*.06*(1-shrink),1-shrink,1-shrink);if(!this.reduced)this.exitBody.rotation.z=Math.sin(t*9)*.13*(1-shrink);this.paws?.forEach((paw,i)=>{if(t<4)paw.rotation.z=(i?1:-1)*(.3+Math.sin(t*14)*.5)});this.bubble.visible=t<5;this.bubble.scale.setScalar(1+shrink*.12);this.bubble.material.opacity=this.reduced?.06:.12;this.popRing.material.opacity=(1-pop)*(t>=5?.65:0);this.popRing.scale.setScalar(1+pop*.9)},
 clear(){if(this.glassSpark){this.glassSpark.traverse(o=>{o.geometry?.dispose();o.material?.dispose()});this.glassSpark.removeFromParent();this.glassSpark=null}this.waiting=0;this.started=null;if(!this.root)return;const geometries=new Set(),materials=new Set();this.root.traverse(o=>{if(o.geometry)geometries.add(o.geometry);if(o.material)materials.add(o.material)});this.root.removeFromParent();geometries.forEach(g=>g.dispose());materials.forEach(m=>m.dispose());this.robotMatcap?.dispose();this.robotMatcap=null;this.root=null;this.exitBody=null;this.bubble=null;this.popRing=null;this.contactSpark=null},
 remove(){this.clear();this.listeners.forEach(fn=>fn());this.replayButton?.remove();delete window.globiquest.replayXRWelcome}
};AFRAME.registerComponent('xr-welcome',sealDefinition);window.globiquest.createSealModel=parent=>{const model={el:{object3D:parent}};sealDefinition.create.call(model);model.dispose=()=>sealDefinition.clear.call(model);return model};const setup=()=>scene.setAttribute('xr-welcome','');if(scene.hasLoaded)setup();else scene.addEventListener('loaded',setup,{once:true});})();
